"Abstand Anfang / Ende":"Размак почетак / крај",
"Abstand Anfang / Ende macht aus der Lasche eine Teillasche. Weitere geschlossene Profile in der Skizze werden zu Ausschnitten in der Platte. Bohrungen und Fenster in einer Lasche: Mitte entlang der Kante (bei einer gebogenen Kante entlang des Bogens), Mitte ab Ende der Biegung, Größe – sie erscheinen auch in der Abwicklung. Geht eine gebogene Kante ohne Knick in ihre Nachbarkante über und haben beide eine Lasche mit gleichem Biegewinkel, laufen die Laschen ohne Freischnitt ineinander über. „Kontur aus Skizze“ schneidet die geschlossenen Profile einer Skizze aus der Lasche: ihr X läuft entlang der Kante, ihr Y in die Lasche hinein, der Nullpunkt liegt am Kantenanfang auf dem Ende der Biegung (verschiebbar).":"Размак од почетка / краја чини од прирубнице делимичну прирубницу. Додатни затворени профили у скици постају изрези у плочи. Рупе и прозори у прирубници: средина дуж ивице (код закривљене ивице дуж лука), средина од краја савијања, величина – појављују се и у развијеном облику. Ако закривљена ивица без прелома прелази у суседну ивицу и обе имају прирубницу са истим углом савијања, прирубнице прелазе једна у другу без ослободног изреза. „Контура из скице“ изрезује затворене профиле скице из прирубнице: њен X иде дуж ивице, њен Y у прирубницу, нулта тачка лежи на почетку ивице на крају савијања (може се померати).",
