"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"Изаберите све површи које треба да нестану (код џепа зидове и дно, код рупе зид, код заобљења заобљену површ). Суседне површи се продужавају преко празнине. Корак се прерачунава при изменама тела; први пут се за то учитава велико геометријско језгро (неколико секунди).",
