"Das Bild konnte nicht gelesen werden.":"Слика није могла бити прочитана.",
"Das Bild liegt als Vorlage auf der Ebene. Größe, Lage, Drehung und Deckkraft danach im Eigenschaftenfenster einstellen (z. B. Breite nach einer bekannten Abmessung).":"Слика лежи као шаблон на равни. Величину, положај, ротацију и непровидност затим подесите у прозору својстава (нпр. ширину према познатој димензији).",
"Das Ergebnis des Geometriekerns ist unlesbar":"Резултат геометријског језгра је нечитљив",
"Das Ergebnis konnte nicht geschrieben werden":"Резултат није могао бити уписан",
"Das Maß muss größer als 0 sein.":"Кота мора бити већа од 0.",
"Das Netz bleibt ein Dreiecksnetz (kein B-Rep). Bearbeiten unter NETZ: Reparieren, Reduzieren, Glätten, Ebenenschnitt … 3D-Frässtrategien in der Fertigung können es direkt bearbeiten.":"Мрежа остаје троугласта мрежа (није B-Rep). Уређивање под МРЕЖА: Поправи, Смањи, Углади, Пресек равни … 3D стратегије глодања у производњи могу је директно обрађивати.",
"Das Netz hat {0} Dreiecke. Jedes wird eine Fläche des Körpers – das dauert lange und macht den Körper träge. Vorher „Reduzieren“ ist meist besser.\n\nTrotzdem umwandeln?":"Мрежа има троуглова: {0}. Сваки постаје површ тела – то дуго траје и успорава тело. Обично је боље прво „Смањи“.\n\nИпак претворити?",
"Das Netz ist nicht geschlossen. Zuerst „Reparieren“ ausführen – ein Körper braucht eine geschlossene Hülle.":"Мрежа није затворена. Прво извршите „Поправи“ – тело захтева затворену љуску.",
"Das Netz reicht in Z von {0} bis {1} mm, in X von {2} bis {3} mm, in Y von {4} bis {5} mm. Punkte, die weniger als die Toleranz von einer Geraden abweichen, entfallen.":"Мрежа се простире у Z од {0} до {1} mm, у X од {2} до {3} mm, у Y од {4} до {5} mm. Тачке које од праве одступају мање од толеранције отпадају.",
"Das Profil darf die Achse nicht schneiden. Eine offene Linie in der Skizze kann als Achse dienen.":"Профил не сме сећи осу. Отворена линија у скици може послужити као оса.",
"Das Profil mit den jetzigen Werten überschreiben":"Преписати профил тренутним вредностима",
"Das Profil wird entlang einer Linie/eines Linienzugs geführt. Profil am besten senkrecht zum Pfadanfang zeichnen (z. B. Profil auf XZ, Pfad auf XY).":"Профил се води дуж линије/полилиније. Профил је најбоље нацртати управно на почетак путање (нпр. профил на XZ, путања на XY).",
"Das Profil wird von der Skizzenebene aus erhaben oder vertieft geprägt.":"Профил се утискује истакнуто или удубљено полазећи од равни скице.",
"Das Rohteil ist der Quader um den gewählten Körper (plus Versatz).":"Припремак је квадар око изабраног тела (плус додатак).",
"Das Setup hat keine Operationen.":"Сетап нема операција.",
"Das Werkzeug fräst in Kreisen, deren Mitte entlang der Nut wandert. Es ist nie über die volle Breite im Eingriff – das erlaubt große Zustelltiefen und schont Fräser und Spindel. Der Fräser sollte etwa 60 % der Nutbreite haben.":"Алат глође у круговима чије се средиште помера дуж утора. Никад није у захвату целом ширином – то допушта велике дубине резања и штеди глодало и вретено. Глодало би требало да има око 60 % ширине утора.",
"Das Werkzeug schneidet die Fläche nicht":"Алат не сече површ",
"Das Werkzeug schneidet in Richtung der ausgewählten Flächen, bis es die angegebenen Aufmaße erreicht.":"Алат реже у смеру изабраних површи док не досегне задате додатке.",
"Das Werkzeug taucht wie ein Bohrer senkrecht ein, Reihe für Reihe, bis auf das Modell plus Aufmaß. Die Schnittkraft wirkt entlang der Spindel: geeignet für lange Werkzeuge, tiefe Kavitäten und wenig steife Maschinen. Das Werkzeug muss über die Mitte schneiden.{0}":"Алат урања окомито попут бургије, ред по ред, до модела плус додатак. Сила резања делује дуж вретена: погодно за дугачке алате, дубоке шупљине и мање круте машине. Алат мора резати преко средишта.{0}",
"Das Werkzeug vermeidet diese Flächen unter Berücksichtigung der angegebenen Sicherheitsabstände (Spanner, Schraubstock).":"Алат избегава ове површи уз поштовање задатих сигурносних размака (стезачи, менгеле).",
"Das Werkzeug vermeidet diese Flächen, während es in der Nähe liegende Flächen bearbeitet, und hält die Sicherheitsabstände ein.":"Алат избегава ове површи док обрађује оближње површи и поштује сигурносне размаке.",
"Das erste Esc bricht nur das Werkzeug oder die Auswahl ab – ein Esc zu viel schließt die Skizze nicht":"Први Esc прекида само алат или избор – вишак Esc не затвара скицу",
"Das ist keine Bohrung (Verrundung oder Zapfen) – bitte die Innenwand einer Bohrung anklicken.":"Ово није рупа (заобљење или чеп) – кликните на унутрашњи зид рупе.",
"Das ist keine Bohrung (Zylinderfläche) – bitte die Bohrungswand anklicken.":"Ово није рупа (цилиндрична површ) – кликните на зид рупе.",
"Das ist keine WerkFab-Design-Datei.":"Ово није датотека дизајна WerkFab.",
"Das ist keine schräge Kante – beide Enden der Fasenkante anklicken.":"Ово није коса ивица – кликните на оба краја ивице скошења.",
"Datei":"Датотека",
"Datei ist keine WerkFab-Einstellungsdatei.":"Датотека није WerkFab датотека подешавања.",
"Datei konnte nicht geöffnet werden:":"Датотека се није могла отворити:",
"Dateiendung":"Екстензија датотеке",
