"Dateiname":"Назив датотеке",
"Daten und Speicher":"Подаци и меморија",
"Datenpanel":"Панел података",
"Datenpanel ein-/ausblenden":"Приказати/сакрити панел са подацима",
"Datenpanel öffnen…":"Отворити панел са подацима…",
"Datum":"Датум",
"Datum/Uhrzeit":"Датум/време",
"Deaktivieren":"Деактивирај",
"Deckkraft":"Непровидност",
"Deckkraft der Fenster":"Непровидност прозора",
"Der Durchmesser würde null oder negativ – Abstand verkleinern":"Пречник би постао нула или негативан – смањите растојање",
"Der Gewindefräser läuft im vollen Material: Den Zapfen vorher freifräsen (2D-Kontur außen um den Zapfen bis zur Gewindetiefe).":"Глодало за навоје ради у пуном материјалу: претходно ослободите чеп глодањем (2D контура споља око чепа до дубине навоја).",
"Der Körper hat auf dieser Ebene keinen Umriss.":"Тело на овој равни нема обрис.",
"Der Körper wird mit den Dreiecken der Anzeige als Netz übernommen. Er selbst bleibt erhalten; spätere Änderungen am Körper ändern das Netz nicht.":"Тело се преузима као мрежа са троугловима приказа. Само тело остаје сачувано; касније измене тела не мењају мрежу.",
"Der Körper wird um seine senkrechte Mittelachse abgetastet und als Halterkontur (Abschnitte) in der Dokument-Werkzeugbibliothek gespeichert.":"Тело се скенира око своје окомите средишње осе и чува као контура држача (сегменти) у библиотеци алата документа.",
"Der Punkt, um den sich die Ansicht dreht (bei freiem Orbit). „Unter dem Mauszeiger“: die Stelle des Modells, an der die Drehung beginnt.":"Тачка око које се поглед ротира (код слободног орбита). „Испод показивача миша“: место на моделу на којем почиње ротација.",
"Der Radius wächst gleichmäßig vom Anfang zum Ende jeder gewählten Kante. Welches Ende der Anfang ist, legt die Kante fest – bei Bedarf tauschen.":"Полупречник равномерно расте од почетка до краја сваке изабране ивице. Који је крај почетак одређује ивица – по потреби замените.",
"Der Rand einer Fläche ist eine geschlossene Kette: Mit „durchlaufend“ läuft der Radius einmal ringsum, ohne diese Option auf jeder Kante für sich vom Anfangs- zum Endradius.":"Руб површи је затворен низ: са опцијом „непрекидно“ полупречник се мења једном око целог руба, а без те опције на свакој ивици посебно од почетног до крајњег полупречника.",
"Der Schnitt trifft keinen Körper – es wird kein Material entfernt.":"Рез не погађа ниједно тело – не уклања се материјал.",
"Der Text steht als Kommentar an dieser Stelle im Programm.":"Текст се налази као коментар на овом месту у програму.",
"Der erste Abstand wird auf der Fläche gemessen, die mehr nach oben (Z) zeigt, der zweite Abstand bzw. der Winkel gilt zur anderen Fläche. „Seiten tauschen“ kehrt das um. Tangential anschließende Kanten laufen mit.":"Прво растојање мери се на површи која је више окренута нагоре (Z), друго растојање односно угао односи се на другу површ. „Замени стране“ то обрће. Тангентно повезане ивице прате се заједно.",
"Der gewählte Körper ist das Rohteil (z. B. ein Guss- oder Schmiederohling). Er wird selbst nicht bearbeitet.":"Изабрано тело је припремак (нпр. одливак или откивак). Оно само се не обрађује.",
"Der große Geometriekern ist noch nicht geladen":"Велико геометријско језгро још није учитано",
"Der große Geometriekern wird geladen – dieser Schritt rechnet gleich von selbst nach":"Учитава се велико геометријско језгро – овај корак ће се ускоро сам прерачунати",
