"Drehen: Drehpunkt anklicken, dann den Winkel mit der Maus zeigen (Vorschau). Esc beendet.":"Ротирање: кликните тачку ротације, затим мишем покажите угао (преглед). Esc завршава.",
"Drehen: Durchmesser, auf dem der Revolver schaltet (Okuma, LinuxCNC). 0 = Rohteil-Ø + 200 mm":"Стругање: пречник на коме се револвер окреће (Okuma, LinuxCNC). 0 = Ø припремка + 200 mm",
"Drehen: Elemente wählen, dann Drehpunkt anklicken und den Winkel mit der Maus zeigen (Vorschau); auch als Kopie":"Ротирај: изаберите елементе, затим кликните тачку ротације и мишем покажите угао (преглед); и као копију",
