"Drehen: Gewindezyklus":"Стругање: циклус навоја",
"Drehen: Polar-Interpolation aus":"Стругање: поларна интерполација искључена",
"Drehen: Polar-Interpolation ein (X Durchmesser, C in mm; leer = X/C in Grad)":"Стругање: поларна интерполација укључена (X пречник, C у mm; празно = X/C у степенима)",
"Drehen: Schlichtzyklus (Kontur des Schruppzyklus)":"Стругање: циклус завршне обраде (контура циклуса грубе обраде)",
