"Drehen: Winkel (°, gegen den Uhrzeigersinn); Drehpunkt X; Drehpunkt Y; Kopien (0 = drehen)":"Ротирање: угао (°, супротно од смера казаљке на сату); тачка ротације X; тачка ротације Y; копије (0 = ротирај)",
"Drehen: Y-Achse aus":"Токарење: Y-оса искључена",
