"Drehen: Z vor der Planfläche, auf dem der Revolver schaltet. 0 = Sicherheitsabstand + 100 mm":"Стругање: Z испред чеоне површи на коме се револвер окреће. 0 = сигурносно растојање + 100 mm",
"Drehen: Zylinder-Interpolation aus":"Стругање: цилиндрична интерполација искључена",
"Drehen: Zylinder-Interpolation ein ({cylr} = Radius; leer = Z/C ohne)":"Стругање: цилиндрична интерполација укључена ({cylr} = полупречник; празно = Z/C без)",
