"Drehgeschwindigkeit":"Брзина ротирања",
"Drehmaschine mit Y-Achse: Schlüsselflächen, Konturen und Taschen auf der Planfläche fahren mit feststehendem Teil (C fest) in X und Y – genauer als die Polar-Interpolation. Was über den Y-Weg hinausgeht, bleibt bei der Polar-Interpolation.":"Струг са Y-осом: кључне површине, контуре и џепови на челу изводе се са непокретним делом (C фиксна) у X и Y – прецизније од поларне интерполације. Оно што прелази Y-ход остаје на поларној интерполацији.",
