"Durchzug":"Овратник",
"Durchzug {0}: Vorbohrung Ø {1} mm wird auf Ø {2} mm aufgeweitet (Faktor {3}) – der Rand reißt dabei meist ein.":"Овратник {0}: предбушена рупа Ø {1} mm проширује се на Ø {2} mm (фактор {3}) – руб притом углавном пукне.",
"Durchzug {0}: Vorbohrung Ø {1} mm wird auf Ø {2} mm aufgeweitet (Faktor {3}).":"Овратник {0}: предбушена рупа Ø {1} mm проширује се на Ø {2} mm (фактор {3}).",
"Durchzug {0}: liegt {1} mm neben dem Rand (weniger als 2 × Blechdicke) – der Rand beult aus.":"Овратник {0}: лежи {1} mm од руба (мање од 2 × дебљина лима) – руб се избочи.",
"Durchzug {0}: zu hoch für diese Bohrung (die Vorbohrung bliebe ohne Durchmesser)":"Овратник {0}: превисок за ову рупу (предбушеној рупи не би остао никакав пречник)",
"Durchzug: der Rand einer runden Bohrung wird zu einem Kragen hochgezogen, etwa als Gewindedurchzug. Der Bohrungsdurchmesser der Skizze ist der fertige Innendurchmesser; im Zuschnitt wird die kleinere Vorbohrung geschnitten.":"Овратник: руб округле рупе извлачи се у овратник, на пример као извлачење за навој. Пречник рупе у скици јесте готови унутрашњи пречник; у кроју се изрезује мања предбушена рупа.",
