"Ebene Flächen des Körpers werden entlang ihrer Normalen extrudiert. Automatisch: nach außen = Material hinzufügen, nach innen (negativ) = ausschneiden.":"Равне површи тела екструдирају се дуж својих нормала. Аутоматски: према споља = додај материјал, према унутра (негативно) = исеци.",
