"Eigene Kurzbefehle: in der Symbolleiste das Gruppenmenü (▾) öffnen, beim Befehl auf ⋮ klicken → „Tastaturkurzbefehl ändern …“.":"Сопствене пречице: у траци са алаткама отворите мени групе (▾), код наредбе кликните ⋮ → „Промени пречицу на тастатури …“.",
"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"Сопствене коте и напомене могу се на листу повлачити мишем (растојање котне линије, угао линије напомене, полупречник угаоног лука). Клик на два угла = линеарна кота. Клик на руб кружнице у горњем погледу = пречник (односно полупречник). Угао: прво теме, затим по једна тачка на оба крака. Скошење: оба краја косе ивице – даје нпр. 2×45°. У текстуалном пољу иза сваке коте налази се додатак попут ±0,1, H7 или 4×.",
