"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"Прво кликните на површ на телу које се помера, затим на циљну површ на другом телу. Тело се ротира и помера док прва тачка клика не легне на другу и површи не легну једна на другу.",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"Прво кликните на ивицу на телу које се помера, затим на циљну ивицу на другом телу. Праве ивице се поклапају (средина на средину); код кружних ивица – рупа и чеп – осе се усмеравају исто и центри се спајају.",
"Erst ein Setup anlegen.":"Прво направите сетап.",
"Erst ein Setup mit Operationen anlegen.":"Прво направите сетап са операцијама.",
"Erst eine Skizze oder Konstruktionsebene wählen – dann schaut Strg+8 senkrecht darauf.":"Прво изаберите скицу или конструкциону раван – тада Ctrl+8 гледа управно на њу.",
"Erst einen Körper in KONSTRUKTION erstellen oder ein Netz (STL) einfügen.":"Прво направите тело у КОНСТРУКЦИЈА или уметните мрежу (STL).",
