"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"Кликните површ тела: њен руб улази у скицу као контура. Клик на ивицу пројектује само ту ивицу (кругови остају кругови). Пројектована геометрија је љубичаста.",
