"Flächen (aufeinander legen)":"Површи (положи једну на другу)",
"Flächen am Körper":"Површи на телу",
"Flächen am Teilende (Zweiflach, Vierkant, Sechskant) mit einem angetriebenen Schaftfräser entlang Z. Schlüsselweite = doppelter Abstand der Fläche von der Drehachse. X und C fahren gemeinsam (Polar-Interpolation, Fanuc G12.1); ohne diese Vorlage im Postprozessor werden kurze X/C-Schritte ausgegeben.":"Површи на крају дела (двоплох, четвороугао, шестоугао) погоњеним вретенастим глодалом дуж Z. Ширина кључа = двострука удаљеност површи од осе ротације. X и C се крећу заједно (поларна интерполација, Fanuc G12.1); без овог шаблона у постпроцесору излазе кратки X/C кораци.",
"Flächen anklicken, die aufgedickt werden (erneut klicken entfernt).":"Кликните површи које се задебљавају (поновни клик уклања).",
