"Fährt alle scharfen Außenkanten ab, die von oben erreichbar sind, und bricht sie um die Entgrattiefe – mit dem Fasenfräser als Fase (Werkzeugachse senkrecht, Spitze außerhalb der Kante), mit dem Kugel-/Lollipop-Fräser gerundet.":"Прелази све оштре спољне ивице доступне одозго и ломи их за дубину скидања срха – глодалом за скошење као скошење (оса алата окомита, врх изван ивице), кугластим/lollipop глодалом заобљено.",
