"Für schräge Richtungen eine Konstruktionsachse anlegen (durch zwei Punkte, einen Zylinder oder zwei Ebenen) – sie erscheint dann hier als Richtung.":"За косе смерове креирајте конструкциону осу (кроз две тачке, цилиндар или две равни) – она се тада појављује овде као смер.",
