"Gerade (radial)":"Право (радијално)",
"Gerade Linien der Skizze, die zu keinem Profil gehören (auch Hilfslinien). Biegung: die Linie ist die Mitte der Biegezone, die Skizze dort der Zuschnitt – das größte Stück der Platte bleibt liegen, alles jenseits der Linie schwenkt mit seinen Laschen mit. Die Linie gilt über die ganze Platte. Sicke: eine Rippe entlang der Linie, im Querschnitt und an den Enden rund; das Blech behält seine Dicke.":"Праве линије скице које не припадају ниједном профилу (и помоћне линије). Савијање: линија је средина зоне савијања, а скица је тамо крој – највећи комад плоче остаје на месту, све с друге стране линије заокреће се са својим прирубницама. Линија важи преко целе плоче. Укрутно ребро: ребро дуж линије, округло у пресеку и на крајевима; лим задржава своју дебљину.",
