"Geschlossen":"Затворено",
"Geschlossen (Gehrung)":"Затворено (коси спој)",
"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"Затворено: краци на две суседне ивице иду до симетрале угла и тамо остављају зазор. Растерећење угла налази се тамо где се зоне савијања укрштају – у развијеном и у савијеном делу. И крак на закривљеној ивици се на правом углу сече на герунг (тамо без растерећења угла).",
"Geschlossene Kette {0}":"Затворени ланац {0}",
"Geschlossene Profile begrenzen den Bereich.":"Затворени профили ограничавају подручје.",
"Geschlossene Profile der aktiven Skizze farbig füllen":"Попуни затворене профиле активне скице бојом",
"Geschlossene Profile werden zu ebenen Flächen – z. B. Deckel und Boden, um Flächen anschließend zu einem Körper zusammenzufügen.":"Затворени профили постају равне површи – нпр. поклопац и дно, да би се површи затим спојиле у тело.",
"Geschnitten ab X":"Пресечено од X",
