"Gestrichelt im DXF/der Skizze: Biegelinien (Anfang und Ende jeder Biegezone). Im DXF liegen sie auf der Ebene BIEGUNG, der Umriss auf Ebene 0.":"Испрекидано у DXF-у/скици: линије савијања (почетак и крај сваке зоне савијања). У DXF-у су на слоју BIEGUNG, обрис на слоју 0.",
