"Importierte Körper sind ohne Konstruktionshistorie, lassen sich aber weiterbearbeiten (Verrundung, Fase, Ausschneiden …) und für CAM verwenden. Mit „Y-Achse oben“ werden Modelle aus Programmen mit Y nach oben richtig hingestellt.":"Увезена тела немају историју конструисања, али се могу даље обрађивати (заобљење, скошење, исецање …) и користити за CAM. Опцијом „Y оса према горе“ модели из програма у којима Y показује нагоре исправно се постављају.",
