"J (relativ)":"J (релативно)",
"Je Skizze die erste Kurve – offen oder geschlossen. Die Kurven werden mit einer Haut verbunden (Fläche ohne Dicke).":"Прва крива сваке скице – отворена или затворена. Криве се повезују омотачем (површ без дебљине).",
"Je Tafel eine Datei. Die Bahn läuft um die halbe Schnittfuge (beim Fräsen den halben Fräser) neben dem Umriss im Abfall; Ausschnitte kommen vor dem Umriss ihres Teils, jede Kontur beginnt mit einem Anschnitt aus dem Abfall. Einschalten mit M3 (Laser: M3 S…), Ausschalten mit M5, Einstechzeit als G4. Nullpunkt ist die linke untere Ecke der Tafel, beim Fräsen Z0 die Blechoberseite. Das Programm vor dem Einsatz an der Maschine oder in einem NC-Simulator prüfen.":"По једна датотека за сваку таблу. Путања иде за пола ширине реза (код глодања за пола глодала) поред обриса у отпаду; изрези долазе пре обриса свог дела, свака контура почиње улазом у рез из отпада. Укључивање са M3 (ласер: M3 S…), искључивање са M5, време пробијања као G4. Нулта тачка је доњи леви угао табле, код глодања је Z0 горња страна лима. Програм проверите на машини или у NC симулатору пре употребе.",
"Jede Achse einzeln: Kante, Ecke, Fläche oder Bohrung anklicken. Nicht gesetzte Achsen kommen vom Rohteilpunkt.":"Свака оса посебно: кликните ивицу, угао, површ или рупу. Осе које нису постављене преузимају се из тачке припремка.",
"Jede Operation als Unterprogramm (LBL) am Programmende, Aufruf mit CALL LBL":"Свака операција као потпрограм (LBL) на крају програма, позив са CALL LBL",
"Jeder Kreis der Skizze ist ein Bohrungsmittelpunkt. Gebohrt wird entgegen der Skizzennormalen (ins Material).":"Сваки круг скице је центар рупе. Бушење иде супротно од нормале скице (у материјал).",
"Jeder Kreis der Skizze wird um die Mitte (in Skizzenkoordinaten) gedreht wiederholt – ein Kreis im Abstand des Teilkreisradius ergibt einen Lochkreis.":"Сваки круг скице понавља се ротиран око центра (у координатама скице) – круг на растојању полупречника подеоног круга даје кружни распоред рупа.",
"Jeder Kreis der Skizze wird zum Raster: Abstände in X und Y der Skizze (auch negativ).":"Сваки круг скице постаје мрежа: размаци по X и Y скице (и негативни).",
"Jetzt einen Punkt auf dem zweiten Schenkel.":"Сада тачка на другом краку.",
"Jetzt jede Richtung einmal bis zum Anschlag: schieben, ziehen, drücken, kippen, drehen (10 s) …":"Сада једном сваки смер до краја: померите, повуците, притисните, нагните, окрените (10 s) …",
