"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"Контуре прате ивицу тамних површина. Средишња линија иде по средини потеза – погодно за гравуре и линијске цртеже. „Линије, лукови и кругови“ препознаје праве ивице, оштре углове, заобљења и кругове; „Полилиније“ прате слику тачку по тачку. Размеру затим по потреби прилагодите опцијом „Калибриши шаблон“ или „Скалирај“.",
