"Kurven einer Skizze auf der Planfläche (quer zur Drehachse) mit einem angetriebenen Fräser entlang Z (X und C fahren gemeinsam; Fanuc: Polar-Interpolation G12.1). Offene Kurven werden hin und zurück gefräst. Tiefe ab Planfläche.":"Кривуље скице на чеоној површи (попречно на осу ротације) погоњеним глодалом дуж Z (X и C се крећу заједно; Fanuc: поларна интерполација G12.1). Отворене кривуље глођу се тамо и назад. Дубина од чеоне површи.",
"Kurven einer Skizze, die längs zur Drehachse liegt, werden auf den Umfang gewickelt und mit einem angetriebenen Fräser gefräst, der zur Achse zeigt (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Die Skizzenebene bestimmt den Winkel, an dem die Kontur sitzt; waagerechte Strecken in der Skizze werden Bögen um das Teil. Tiefe ab Außendurchmesser.":"Кривуље скице која лежи уздужно уз осу ротације намотавају се на обим и глођу погоњеним глодалом окренутим ка оси (Z и C се крећу заједно; Fanuc: цилиндрична интерполација G7.1). Раван скице одређује угао на којем контура лежи; водоравне дужи у скици постају лукови око дела. Дубина од спољног пречника.",
"Kurzbefehl":"Пречица",
"Kurze Wege (bis zum Halteabstand) fährt das Werkzeug unten im Übergangsvorschub statt über die Rückzugshöhe – ohne Kollisionsprüfung, daher klein halten.":"Кратке путање (до растојања задржавања) алат прелази доле прелазним посмаком уместо преко висине повлачења – без провере судара, зато држите мало.",
