"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"Више повезаних ивица рачуна се као једна деоница: полупречник се мења од почетка низа до његовог краја, контролне тачке важе у % целе дужине низа. То рачуна велико геометријско језгро.",
