"Mit Stützpunkten läuft der Radius durch die angegebenen Werte (Lage in % der Kantenlänge). Das rechnet der große Geometriekern; beim ersten Mal lädt er einige Sekunden.":"Са контролним тачкама полупречник пролази кроз задате вредности (положај у % дужине ивице). То рачуна велико геометријско језгро; први пут се учитава неколико секунди.",
"Mit dem 3D-Taster kann nicht zerspant werden":"3D сондом се не може скидати струготина",
"Mit dem Fertigteil vergleichen: grün = auf Maß, blau = Restmaterial, rot = zu tief":"Поређење са готовим делом: зелено = на мери, плаво = преостали материјал, црвено = предубоко",
"Mit der Maus neben eine Kontur fahren (die Seite bestimmt die Richtung) · Esc beendet":"Мишем прећи поред контуре (страна одређује смер) · Esc завршава",
"Mit diesem Werkzeug kann nicht gefräst werden":"Овим алатом се не може глодати",
"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"С урезником само циклус „Урезивање навоја“ – циклус бушења би га сломио",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"Уз више пролаза дубина навоја се глође у корацима који скидају отприлике једнаку количину – штеди мала глодала за навоје и тврде материјале. Пролаз без подешавања још једном прелази последњу путању без додатног корака.",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"Уз „Циклуси бушења“ у NC програму излазе циклуси управљања (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), иначе расписани покрети.",
"Mit „Original behalten“ werden Original und Spiegelbild ein Netz; Punkte auf der Spiegelebene werden verbunden – aus einer offenen Hälfte wird so ein geschlossenes Teil.":"Уз „Задржи оригинал“ оригинал и слика у огледалу постају једна мрежа; тачке на равни огледања се спајају – из отворене половине тако настаје затворен део.",
