"Nicht übernommen (Halter, Taster oder unbekannter Typ): {0}{1}":"Није преузето (држач, тастер или непознат тип): {0}{1}",
"Nichts getroffen – Kante, Ecke, Fläche oder Bohrung anklicken.":"Ништа није погођено – кликните ивицу, угао, површ или рупу.",
"Nichts getroffen – auf das Modell klicken.":"Ништа није погођено – кликните на модел.",
"Nichts gewählt – „Auswählen“ und im Modell anklicken.":"Ништа није изабрано – „Изабери“ и кликните на моделу.",
"Nichts gewählt – „Auswählen“, dann Flächen oder Kanten im Modell anklicken.":"Ништа није изабрано – „Изабери“, затим кликните површи или ивице на моделу.",
"Nichts geändert: Die Nachbarflächen schließen diese Lücke nicht – zusammengehörige Flächen gemeinsam wählen (z. B. Wand und Boden einer Tasche)":"Ништа није промењено: суседне површи не затварају ову празнину – изаберите заједно површи које заједно припадају (нпр. зид и дно џепа)",
"Nichts zu schruppen":"Нема шта грубо обрађивати",
"Nichts zum Umbenennen gewählt.":"Ништа није изабрано за преименовање.",
"Niedrig (0,05 mm)":"Ниско (0,05 mm)",
"Noch kein Dreh-Setup: „Neues Setup“ → Bearbeitung „Drehen“ wählen.":"Још нема сетапа за струганје: „Нови сетап“ → изаберите обраду „Струганје“.",
"Noch kein Fräs-Setup vorhanden.":"Још нема сетапа за глодање.",
"Noch kein Körper gewählt – bis dahin gilt die relative Quadergröße.":"Тело још није изабрано – до тада важи релативна величина квадра.",
"Noch kein Körper vorhanden – erst in KONSTRUKTION modellieren.":"Још нема тела – прво моделујте у КОНСТРУКЦИЈИ.",
"Noch keine Designs gespeichert.":"Још нема сачуваних дизајна.",
"Noch keine Kommentare. Mit + Notizen zum Design festhalten.":"Још нема коментара. Помоћу + забележите белешке уз дизајн.",
"Noch keine Operation":"Још нема операције",
"Noch keine Vorlagen. Eine Vorlage speichert Strategien mit allen Einstellungen (Werkzeug, Schnittdaten, Höhen, Durchgänge, Verknüpfung) zum Wiederverwenden in anderen Setups und Designs.":"Још нема шаблона. Шаблон чува стратегије са свим подешавањима (алат, подаци резања, висине, пролази, повезивање) за поновну употребу у другим сетапима и дизајнима.",
"Noch keine Werkzeuge im Dokument.":"У документу још нема алата.",
"Noch keine. Geometrie wählen und oben unter ABHÄNGIGKEITEN ein Werkzeug anklicken.":"Још нема. Изаберите геометрију и горе под ОГРАНИЧЕЊА кликните алат.",
