"Nullpunkt der Skizze ab Ende der Biegung (in die Lasche hinein) mm":"Нулта тачка скице од краја савијања (унутар прирубнице) mm",
"Nullpunkt der Skizze entlang der Kante (vom Kantenanfang) mm":"Нулта тачка скице дуж ивице (од почетка ивице) mm",
"Nullpunkt gespeichert (Rauschen ±{0} → Totzone {1}). Jetzt optional „Maximalausschlag messen“.":"Нулта тачка сачувана (шум ±{0} → мртва зона {1}). Сада по жељи „Измери максимални отклон“.",
