"Nur ASCII-Zeichen":"Само ASCII знакови",
"Nur Außenkonturen":"Само спољашње контуре",
"Nur Außenkonturen (Zapfen) gehen als Steuerungszyklus":"Само спољне контуре (чепови) могу као циклус управљања",
"Nur Durchmesser (Form wie dieses Werkzeug)":"Само пречник (облик као овај алат)",
"Nur Innenkonturen (Öffnungen)":"Само унутрашње контуре (отвори)",
"Nur Rechteck- und Kreistaschen gehen als Steuerungszyklus":"Само правоугаони и кружни џепови могу као циклус управљања",
"Nur Skizze":"Само скица",
"Nur das bearbeiten, was ein größerer Fräser in Ecken stehen gelassen hat.":"Обрађивати само оно што је већа глодалица оставила у угловима.",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"Прелазити само она места контуре која већа глодалица није досегла (унутрашњи углови, уска места). Без улазних/излазних лукова, држача и пролаза завршне обраде; корекција у рачунару.",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"Само тамо где референтни алат није досегао: равна подручја паралелно, стрма подручја као водена линија. Са алатом са списка рачуна се и његов облик – на пример оно што торусно глодало остави у жлебовима.",
"Nur ebene Flächen können als Skizzenebene dienen.":"Само равне површи могу служити као раван скице.",
"Nur ebene Flächen können extrudiert werden":"Могу се екструдирати само равне површи",
"Nur ebene Flächen lassen sich ersetzen":"Заменити се могу само равне површи",
"Nur ebene Flächen und Zylinderflächen (Bohrungen, Zapfen) lassen sich versetzen":"Померити (офсет) се могу само равне и цилиндричне површи (рупе, чепови)",
"Nur ebene Flächen, die nach oben zum Werkzeug zeigen (waagerecht in diesem Setup).":"Само равне површи окренуте навише, ка алату (водоравне у овом сетапу).",
"Nur für Außen-Drehmeißel":"Само за спољашње стругарске ножеве",
"Nur in Operationen verwendete":"Само коришћени у операцијама",
"Nur in diesem Projekt":"Само у овом пројекту",
"Nur mit Korrektur „Im Rechner“.":"Само са корекцијом „У рачунару“.",
"Nur stärkste Achse":"Само најјача оса",
"Nut":"Жлеб",
"Nut angetrieben":"Погоњени жлеб",
"Nut angetrieben (C-Achse)":"Погоњени жљеб (оса C)",
"Nut liegt nicht am Teil":"Жљеб није на делу",
"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"Утор уздуж осе ротације (нпр. утор за клин) погоњеним глодалом окренутим ка оси; главно вретено држи део као C осу. Ширина утора = Ø глодала. Почетак/крај Z у Z модела; ако утор сеже до чеоне површи, глодало улази спреда, иначе урања на почетку. Дубина од спољног пречника.",
"Nutbreite bei Linien":"Ширина утора код линија",
"Nuten":"Утори",
"Nutenfräser":"Глодало за жљебове",
"Nuttiefe":"Дубина утора",
"Nuttiefe angeben":"Навести дубину жљеба",
"Nuttiefe {0} mm ist größer als der Radius {1} mm":"Дубина жљеба {0} mm већа је од радијуса {1} mm",
"Nächstes Werkzeug schon vorbereiten (TOOL DEF bzw. T-Wort)":"Унапред припреми следећи алат (TOOL DEF односно T-реч)",
"O-Ring (ISO 3601)":"О-прстен (ISO 3601)",
"OBEN":"ГОРЕ",
"OK":"OK",
"Oben":"Горе",
"Oben (Z+ nach oben)":"Горе (Z+ према горе)",
"Oben auf FERTIGUNG wechseln für CAM.":"Горе пређите на ПРОИЗВОДЊА за CAM.",
"Obere Höhe":"Горња висина",
"Oberer Ø":"Горњи Ø",
