"Oberflächenzeichen hinzufügen":"Додај ознаку површине",
"Oberflächenzeichen und Bezüge bitte in der Vorder-, Drauf- oder Seitenansicht setzen.":"Ознаке површине и базе поставите у предњи, горњи или бочни поглед.",
