"Oberseite des Rechtecks bzw. Taschenboden":"Горња страна правоугаоника односно дно џепа",
"Oder Skizze":"Или скица",
"Offen (Laschen gekürzt)":"Отворено (краци скраћени)",
"Offene Flächen":"Отворене површи",
"Offene Kanten werden rot angezeigt. „Reparieren“ schließt Löcher.":"Отворене ивице приказују се црвено. „Поправи“ затвара рупе.",
"Offene Linie in einer Skizze wählen":"Изаберите отворену линију у скици",
"Offene oder geschlossene Kurven werden senkrecht zur Skizze gezogen – es entsteht eine Fläche (Wand ohne Dicke). Mit „Aufdicken“ oder „Zusammenfügen“ wird daraus ein Volumen.":"Отворене или затворене криве извлаче се управно на скицу – настаје површ (зид без дебљине). Опцијом „Задебљај“ или „Споји“ из ње настаје запремина.",
"Offene oder geschlossene Kurven werden um die Achse gedreht – es entsteht eine Fläche, kein Volumen.":"Отворене или затворене криве ротирају се око осе – настаје површ, а не запремина.",
"Ohne eigene Taste gilt der Standard „{0}“.":"Без сопственог тастера важи подразумевано „{0}“.",
"Ohne „Modelliert“ wird das Gewinde nur dargestellt (schnell). Modelliert wird die Gewindeform wirklich ausgeschnitten, z. B. für 3D-Druck. Bohrung für M8 = Ø6,8.":"Без опције „Моделиран“ навој се само приказује (брзо). Код моделираног навоја облик навоја се заиста исеца, нпр. за 3D штампу. Рупа за M8 = Ø6,8.",
"Okuma OSP Drehen":"Okuma OSP стругање",
"Okuma OSP-M Fräsen":"Okuma OSP-M глодање",
"Okuma OSP: G28/G53 fahren dort nicht auf Maschinenkoordinaten (G53 hebt die Werkzeuglängenkorrektur auf) – Rückzug auf Sicherheitshöhe, keine XY-Referenzfahrt ausgegeben":"Okuma OSP: G28/G53 ту не иду на машинске координате (G53 поништава корекцију дужине алата) – повлачење на сигурносну висину, XY референтни ход није исписан",
"Okuma OSP: keine Glättungsfunktion ausgegeben (G5.1 ist Fanuc) – Hi-Cut/Super-NURBS an der Maschine einstellen":"Okuma OSP: функција заглађивања није исписана (G5.1 је Fanuc) – Hi-Cut/Super-NURBS подесите на машини",
"Okuma: Korrektur+Werkzeug+Schneide (z. B. 010101)":"Okuma: корекција+алат+оштрица (нпр. 010101)",
"OpenCascade (alle Funktionen)":"OpenCascade (све функције)",
"OpenCascade: alle Funktionen. Rust-Kern (truck, experimentell): Grundkörper, Extrusion, Rotation, Bohrung, Muster, Spiegeln, Verschieben, Skalieren, Kombinieren und STEP-Export – andere Features werden als „noch nicht unterstützt“ markiert.":"OpenCascade: све функције. Rust језгро (truck, експериментално): основна тела, екструзија, ротација, рупа, низ, огледање, померање, скалирање, комбиновање и STEP извоз – остали featureи означени су као „још није подржано“.",
