"Positiv = nach außen (mehr Material), negativ = nach innen. Ebene Flächen verschieben sich; bei einer Bohrung oder einem Zapfen ändert sich der Radius um den Abstand – eine Bohrung wird mit positivem Abstand enger.":"Позитивно = према споља (више материјала), негативно = према унутра. Равне површи се померају; код рупе или чепа полупречник се мења за износ растојања – рупа постаје ужа са позитивним растојањем.",
