"Schruppt die Bohrung von der Vorbohrung nach außen (0,2 mm Schlichtaufmaß) und schlichtet sie dann bis zum Grund. Die Bohrstange muss in die Vorbohrung passen.":"Грубо обрађује рупу од предбушења према споља (0,2 mm додатка за завршну обраду), а затим је завршно обрађује до дна. Бушаћа шипка мора стати у предбушену рупу.",
"Schruppt simultan 4-achsig von außen nach innen: je Zustellung eine Spirale um die A-Achse (abwechselnd in +X und −X), nie tiefer als das Teil plus Aufmaß. Mit Schaft- oder Kugelfräser.":"Грубо обрађује симултано у 4 осе споља ка унутра: по кораку једна спирала око A осе (наизменично у +X и −X), никад дубље од дела плус додатак. Вретенастим или кугластим глодалом.",
