"Tasche auf dem Umfang aus den geschlossenen Konturen einer Skizze, die längs zur Drehachse liegt (innere Konturen bleiben als Inseln stehen). Die Skizze wird auf den Durchmesser gewickelt; ein angetriebener Schaftfräser, der zur Achse zeigt, räumt von innen nach außen (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Der Fräser taucht auf einer Rampe entlang des innersten Rings ein.":"Џеп на обиму од затворених контура скице која лежи уздужно уз осу обртања (унутрашње контуре остају као острва). Скица се намотава на пречник; погоњена вретенаста глодала усмерена ка оси уклања материјал изнутра ка споља (Z и C крећу се заједно; Fanuc: цилиндрична интерполација G7.1). Глодало улази по рампи дуж најунутрашњег прстена.",
"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"Џеп у чеоној површи из затворених контура скице (унутрашње контуре остају као острва), погоњеним вретенастим глодалом дуж Z. Чисти се изнутра према споља; глодало урања по рампи дуж најунутрашније путање и унутар једног нивоа остаје доле. X и C се крећу заједно (Fanuc: поларна интерполација G12.1). Дубина од чеоне површи.",
"Tasche mit Insel – der Steuerungszyklus kann keine Inseln":"Џеп са острвом – циклус управљања не подржава острва",
