"{0}: Postprozessor ohne Vorlage „C-Achse und angetriebenes Werkzeug ein“ – C-Achse und Werkzeugspindel von Hand einschalten":"{0}: Постпроцесор без шаблона „C оса и погоњени алат укључени“ – C осу и вретено алата укључите ручно",
