"„+“ = Werkzeug wird neu angelegt. Schnittdaten sind Richtwerte für Hartmetall ({0}){1}; Kühlung: {2}.":"„+“ = алат ће бити креиран. Подаци резања су оријентационе вредности за тврди метал ({0}){1}; хлађење: {2}.",
"„Ineinander schachteln“ legt die Zuschnitte in die Lücken und Buchten ihrer Nachbarn und in deren Ausschnitte (ohne 90°-Drehen nur um 180° gewendet); der Abstand wird nie unterschritten. Ohne den Haken liegen sie nach ihrem umschließenden Rechteck in Reihen. Mit „Skizze + Körper“ entstehen flache Körper in Blechdicke, die sich in der Fertigung mit 2D-Kontur ausschneiden lassen.":"„Уклопити једно у друго“ слаже кројеве у празнине и увале суседних делова и у њихове изрезе (без окретања за 90° само окренуто за 180°); размак се никада не смањује. Без квачице леже у редовима према свом описаном правоугаонику. Уз „Скица + тела“ настају равна тела дебљине лима која се у производњи могу изрезати 2D контуром.",
"„Innen/Außen“ braucht geschlossene Konturen – offene Kurven mit „Auf der Kurve“ fräsen":"„Изнутра/Споља“ захтева затворене контуре – отворене криве глодати опцијом „На кривој“",
"„Skizze fertig“ → Extrusion, Rotation oder Bohrung.":"„Заврши скицу“ → Екструзија, Ротација или Рупа.",
