"⚠ Jedes NC-Programm vor dem ersten Lauf prüfen: an der Maschine im Probelauf (Einzelsatz, reduzierter Eilgang) oder in einem externen NC-Simulator. Die Simulation hier ersetzt das nicht – Nutzung auf eigene Gefahr, ohne Gewährleistung.":"⚠ Сваки NC програм проверите пре првог покретања: на машини у пробном раду (блок по блок, смањен брзи ход) или у спољном NC симулатору. Симулација овде то не замењује – употреба на сопствену одговорност, без гаранције.",
