"⚠ Nach der letzten Änderung des Körpers war nicht eindeutig, welche Kante oder Fläche gemeint ist. Bitte prüfen – bei Bedarf löschen und neu projizieren.":"⚠ После последње промене тела није било јасно која се ивица или површ мисли. Молимо проверите – по потреби обришите и поново пројектујте.",
"⚠ Programmlogik (JavaScript) wird nicht ausgeführt: Sonderfunktionen, 4./5. Achse, Messzyklen und Maschinenoptionen bitte im Postprozessor-Editor prüfen.":"⚠ Програмска логика (JavaScript) се не извршава: посебне функције, 4./5. осу, мерне циклусе и опције машине проверите у уређивачу постпроцесора.",
